@Bean
SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
        .formLogin(form -> form
                .defaultSuccessUrl("/api/dashboard", true)
                .failureUrl("/login?failed"));
    return http.build();
}

// POST /login z poprawnymi danymi
// -> status 302, Location: /api/dashboard (nadpisuje oryginalny cel, bo alwaysUse=true)

// POST /login z blednym haslem
// -> status 302, Location: /login?failed (wlasny adres z failureUrl(...))

http.authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
    .formLogin(form -> form.loginPage("/login"));
// GET /login -> przekierowanie do /login -> przekierowanie do /login -> ...

http.authorizeHttpRequests(auth -> auth
        .requestMatchers("/login").permitAll()
        .anyRequest().authenticated())
    .formLogin(form -> form.loginPage("/login"));
// GET /login -> 200 (dostepne bez logowania)
